package io.github.iamthecodedecoded.banktabshortcuts;

import java.awt.event.KeyEvent;

final class BankTabNavigator
{
	static final int NONE = -1;
	static final int NEXT = 10;
	static final int PREVIOUS = -10;
	static final int TAB_COUNT = 9;

	private BankTabNavigator()
	{
	}

	static int requestFor(KeyEvent event)
	{
		if (!event.isControlDown() || event.isAltDown() || event.isAltGraphDown() || event.isMetaDown())
		{
			return NONE;
		}

		// Key Remapping rewrites keyCode; AWT preserves the original extended code.
		int keyCode = event.getExtendedKeyCode();
		if (keyCode == KeyEvent.VK_UNDEFINED)
		{
			keyCode = event.getKeyCode();
		}

		if (keyCode == KeyEvent.VK_TAB)
		{
			return event.isShiftDown() ? PREVIOUS : NEXT;
		}

		if (!event.isShiftDown()
			&& keyCode >= KeyEvent.VK_0
			&& keyCode <= KeyEvent.VK_9)
		{
			return keyCode - KeyEvent.VK_0;
		}
		if (!event.isShiftDown()
			&& keyCode >= KeyEvent.VK_NUMPAD0
			&& keyCode <= KeyEvent.VK_NUMPAD9)
		{
			return keyCode - KeyEvent.VK_NUMPAD0;
		}

		return NONE;
	}

	static int targetFor(int request, int currentTab, int[] tabItemCounts)
	{
		if (tabItemCounts == null || tabItemCounts.length != TAB_COUNT)
		{
			throw new IllegalArgumentException("tabItemCounts must contain exactly nine entries");
		}

		if (request == 0)
		{
			return 0; // The all-items view exists even without numbered tabs.
		}

		if (request >= 1 && request <= TAB_COUNT)
		{
			return exists(request, tabItemCounts) ? request : NONE;
		}

		if (request != NEXT && request != PREVIOUS)
		{
			return NONE;
		}

		int step = request == NEXT ? 1 : -1;
		int startingTab = currentTab >= 1 && currentTab <= TAB_COUNT
			? currentTab
			: (step > 0 ? 0 : TAB_COUNT + 1);

		for (int offset = 1; offset <= TAB_COUNT; offset++)
		{
			int candidate = Math.floorMod(startingTab - 1 + step * offset, TAB_COUNT) + 1;
			if (exists(candidate, tabItemCounts))
			{
				return candidate;
			}
		}

		return NONE;
	}

	private static boolean exists(int tab, int[] tabItemCounts)
	{
		return tabItemCounts[tab - 1] > 0;
	}
}

package io.github.iamthecodedecoded.banktabshortcuts;

import com.google.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class BankTabNumbersOverlay extends Overlay
{
	// Native tab click-targets occupy children 10..19 (All, then tabs 1..9).
	private static final int FIRST_TAB_CHILD = 10;
	private final Client client;
	private final BankTabShortcutsConfig config;

	@Inject
	BankTabNumbersOverlay(Client client, BankTabShortcutsConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Bankmain.TABS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showTabNumbers())
		{
			return null;
		}
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		Widget tabs = client.getWidget(InterfaceID.Bankmain.TABS);
		if (items == null || items.isHidden() || tabs == null || tabs.isHidden())
		{
			return null;
		}
		Widget all = tabs.getChild(FIRST_TAB_CHILD);
		if (all == null || all.isHidden())
		{
			return null;
		}

		// RuneLite renders overlays on the client thread; never retain widget references.
		for (int tab = 0; tab <= BankTabNavigator.TAB_COUNT; tab++)
		{
			if (tab > 0 && client.getVarbitValue(VarbitID.BANK_TAB_1 + tab - 1) <= 0)
			{
				continue;
			}
			Widget widget = tabs.getChild(FIRST_TAB_CHILD + tab);
			if (widget == null || widget.isHidden())
			{
				continue;
			}
			String[] actions = widget.getActions();
			if (actions != null && Arrays.asList(actions).contains("New tab"))
			{
				continue;
			}
			Rectangle bounds = widget.getBounds();
			if (bounds.width <= 0 || bounds.height <= 0)
			{
				continue;
			}
			Graphics2D label = (Graphics2D) graphics.create();
			try
			{
				label.clip(tabs.getBounds());
				label.clip(bounds);
				label.setFont(FontManager.getRunescapeSmallFont().deriveFont((float) Math.max(8, Math.min(16, config.numberSize()))));
				int x = bounds.x + 2;
				int y = bounds.y + 2 + label.getFontMetrics().getAscent();
				String text = Integer.toString(tab);
				label.setColor(new Color(0, 0, 0, config.numberColor().getAlpha() / 2));
				label.drawString(text, x + 1, y + 1);
				label.setColor(config.numberColor());
				label.drawString(text, x, y);
			}
			finally
			{
				label.dispose();
			}
		}
		return null;
	}
}

package io.github.iamthecodedecoded.banktabshortcuts;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("banktabshortcuts")
public interface BankTabShortcutsConfig extends Config
{
	@ConfigItem(keyName = "showTabNumbers", name = "Show tab numbers",
		description = "Show subtle shortcut numbers at the top-left of native bank tabs", position = 0)
	default boolean showTabNumbers()
	{
		return false;
	}

	@Alpha
	@ConfigItem(keyName = "numberColor", name = "Number color",
		description = "Color and opacity of the tab shortcut numbers", position = 1)
	default Color numberColor()
	{
		return new Color(210, 200, 175, 220);
	}

	@Range(min = 8, max = 16)
	@ConfigItem(keyName = "numberSize", name = "Number size",
		description = "Font size of the tab shortcut numbers (8-16)", position = 2)
	default int numberSize()
	{
		return 10;
	}
}

package io.github.iamthecodedecoded.banktabshortcuts;

import com.google.inject.Inject;
import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Bank Tab Shortcuts",
	description = "Navigate native bank tabs with Ctrl+0 through Ctrl+9, Ctrl+Tab, and optional tab numbers",
	tags = {"bank", "tabs", "keyboard", "hotkeys", "shortcuts"}
)
public class BankTabShortcutsPlugin extends Plugin implements KeyListener
{
	private static final Logger LOG = LoggerFactory.getLogger(BankTabShortcutsPlugin.class);
	// Native tab icons, separator headings and potion storage use this script.
	// RuneLite cs2-scripts: [clientscript,bankmain_switchtab] (not exposed by ScriptID).
	private static final int BANKMAIN_SWITCHTAB = 504;

	private static final int[] BANK_TAB_COUNT_VARBITS =
	{
		VarbitID.BANK_TAB_1,
		VarbitID.BANK_TAB_2,
		VarbitID.BANK_TAB_3,
		VarbitID.BANK_TAB_4,
		VarbitID.BANK_TAB_5,
		VarbitID.BANK_TAB_6,
		VarbitID.BANK_TAB_7,
		VarbitID.BANK_TAB_8,
		VarbitID.BANK_TAB_9
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankTabNumbersOverlay numbersOverlay;

	@Provides
	BankTabShortcutsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankTabShortcutsConfig.class);
	}

	// Only immutable, client-thread-produced data crosses into the AWT key listener.
	private volatile int availableTabs;
	private volatile Object activation;
	private volatile int rememberedTab = BankTabNavigator.NONE;
	private volatile boolean bankOpen;

	@Override
	protected void startUp()
	{
		availableTabs = 0;
		rememberedTab = BankTabNavigator.NONE;
		bankOpen = false;
		activation = new Object();
		keyManager.registerKeyListener(this);
		overlayManager.add(numbersOverlay);
	}

	@Override
	protected void shutDown()
	{
		activation = null;
		availableTabs = 0;
		rememberedTab = BankTabNavigator.NONE;
		bankOpen = false;
		keyManager.unregisterKeyListener(this);
		overlayManager.remove(numbersOverlay);
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (activation == null)
		{
			return;
		}

		try
		{
			int tabs = 0;
			Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
			if (bankItems != null && bankOpen)
			{
				// Respect other views/plugins that change the selection without script 504.
				if (rememberedTab != BankTabNavigator.NONE
					&& client.getVarbitValue(VarbitID.BANK_CURRENTTAB) != rememberedTab)
				{
					rememberedTab = BankTabNavigator.NONE;
				}
			}
			if (bankItems != null && !bankItems.isHidden())
			{
				bankOpen = true;
				tabs = 1; // Bit zero is the all-items view.
				int[] counts = readTabItemCounts();
				for (int i = 0; i < counts.length; i++)
				{
					if (counts[i] > 0)
					{
						tabs |= 1 << (i + 1);
					}
				}
			}
			availableTabs = tabs;
		}
		catch (RuntimeException exception)
		{
			availableTabs = 0;
			LOG.error("BTS_BANK_STATE_FAILED", exception);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			try
			{
				if (bankOpen && rememberedTab != BankTabNavigator.NONE
					&& client.getVarbitValue(VarbitID.BANK_CURRENTTAB) != rememberedTab)
				{
					rememberedTab = BankTabNavigator.NONE;
				}
			}
			catch (RuntimeException exception)
			{
				rememberedTab = BankTabNavigator.NONE;
				LOG.error("BTS_TAB_CAPTURE_FAILED", exception);
			}
			availableTabs = 0;
			bankOpen = false;
			// A key queued for the closed bank must not run in a newly opened bank.
			if (activation != null)
			{
				activation = new Object();
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.LOGGING_IN
			|| state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			rememberedTab = BankTabNavigator.NONE;
			bankOpen = false;
			availableTabs = 0;
			if (activation != null)
			{
				activation = new Object();
			}
		}
	}

	// Run before Bank Tags' default-priority init so its remembered tag can still win.
	@Subscribe(priority = 1)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (activation == null)
		{
			return;
		}
		if (event.getScriptId() == BANKMAIN_SWITCHTAB)
		{
			// A subsequent native click owns the server's remembered selection again.
			rememberedTab = BankTabNavigator.NONE;
		}
		else if (event.getScriptId() == ScriptID.BANKMAIN_INIT && !bankOpen)
		{
			bankOpen = true;
			if (rememberedTab == BankTabNavigator.NONE)
			{
				return;
			}
			try
			{
				int target = BankTabNavigator.targetFor(rememberedTab, 0, readTabItemCounts());
				if (target == BankTabNavigator.NONE)
				{
					rememberedTab = BankTabNavigator.NONE;
					return;
				}
				// Bank open resyncs the server's last clicked tab. Override only the local
				// view before native init builds it; never send a synthetic tab click.
				client.setVarbit(VarbitID.BANK_CURRENTTAB, target);
			}
			catch (RuntimeException exception)
			{
				rememberedTab = BankTabNavigator.NONE;
				LOG.error("BTS_TAB_RESTORE_FAILED", exception);
			}
		}
	}

	@Override
	public void keyPressed(KeyEvent event)
	{
		int request = BankTabNavigator.requestFor(event);
		Object currentActivation = activation;
		int tabs = availableTabs;
		if (event.isConsumed() || request == BankTabNavigator.NONE || currentActivation == null || tabs == 0)
		{
			return;
		}

		if (request >= 0 && request <= BankTabNavigator.TAB_COUNT && (tabs & (1 << request)) == 0)
		{
			return;
		}
		if ((request == BankTabNavigator.NEXT || request == BankTabNavigator.PREVIOUS) && (tabs & ~1) == 0)
		{
			return;
		}

		event.consume();
		clientThread.invoke(() ->
		{
			if (activation == currentActivation)
			{
				navigate(request);
			}
		});
	}

	@Override
	public void keyTyped(KeyEvent event)
	{
	}

	@Override
	public void keyReleased(KeyEvent event)
	{
	}

	private int[] readTabItemCounts()
	{
		int[] counts = new int[BANK_TAB_COUNT_VARBITS.length];
		for (int i = 0; i < BANK_TAB_COUNT_VARBITS.length; i++)
		{
			counts[i] = client.getVarbitValue(BANK_TAB_COUNT_VARBITS[i]);
		}
		return counts;
	}

	private void navigate(int request)
	{
		try
		{
			if (activation == null || availableTabs == 0)
			{
				return;
			}

			Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
			if (bankItems == null || bankItems.isHidden())
			{
				return;
			}

			int target = BankTabNavigator.targetFor(
				request,
				client.getVarbitValue(VarbitID.BANK_CURRENTTAB),
				readTabItemCounts());
			if (target == BankTabNavigator.NONE)
			{
				return;
			}

			Object[] bankBuildArgs = bankItems.getOnInvTransmitListener();
			if (bankBuildArgs == null)
			{
				LOG.warn("BTS_BANK_REBUILD_LISTENER_MISSING request={}", request);
				return;
			}

			client.setVarbit(VarbitID.BANK_CURRENTTAB, target);
			client.runScript(ScriptID.MESSAGE_LAYER_CLOSE, 1, 1, 0);
			client.runScript(bankBuildArgs);
			rememberedTab = target;
		}
		catch (RuntimeException exception)
		{
			rememberedTab = BankTabNavigator.NONE;
			LOG.error("BTS_NAVIGATION_FAILED request={}", request, exception);
		}
	}
}

package io.github.iamthecodedecoded.banktabshortcuts;

import java.awt.Canvas;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class BankTabNavigatorTest
{
	private static final Canvas SOURCE = new Canvas();

	@Test
	public void zeroSelectsAllFromEitherNumberRow()
	{
		assertNotEquals(0, BankTabNavigator.NONE);
		assertEquals(0, BankTabNavigator.requestFor(key(KeyEvent.VK_0, InputEvent.CTRL_DOWN_MASK)));
		assertEquals(0, BankTabNavigator.requestFor(key(KeyEvent.VK_NUMPAD0, InputEvent.CTRL_DOWN_MASK)));
		assertEquals(0, BankTabNavigator.targetFor(0, 4, counts()));
	}

	@Test
	public void mapsEveryNumberedShortcut()
	{
		for (int tab = 1; tab <= 9; tab++)
		{
			assertEquals(tab, BankTabNavigator.requestFor(key(KeyEvent.VK_0 + tab, InputEvent.CTRL_DOWN_MASK)));
		}
	}

	@Test
	public void mapsEveryNumpadShortcut()
	{
		for (int tab = 1; tab <= 9; tab++)
		{
			assertEquals(tab, BankTabNavigator.requestFor(key(KeyEvent.VK_NUMPAD0 + tab, InputEvent.CTRL_DOWN_MASK)));
		}
	}

	@Test
	public void recognizesOriginalNumberAfterAnotherListenerRemapsIt()
	{
		KeyEvent event = new KeyEvent(SOURCE, KeyEvent.KEY_PRESSED, 1L,
			InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_2, KeyEvent.CHAR_UNDEFINED)
		{
			@Override
			public int getExtendedKeyCode()
			{
				return KeyEvent.VK_2;
			}
		};
		// Key Remapping changes keyCode; AWT retains the native extended code.
		event.setKeyCode(KeyEvent.VK_F2);
		assertEquals(2, BankTabNavigator.requestFor(event));
	}

	@Test
	public void doesNotTreatPhysicalFunctionKeyAsNumberedShortcut()
	{
		assertEquals(BankTabNavigator.NONE,
			BankTabNavigator.requestFor(key(KeyEvent.VK_F2, InputEvent.CTRL_DOWN_MASK)));
	}

	@Test
	public void mapsForwardAndBackwardCycling()
	{
		assertEquals(BankTabNavigator.NEXT,
			BankTabNavigator.requestFor(key(KeyEvent.VK_TAB, InputEvent.CTRL_DOWN_MASK)));
		assertEquals(BankTabNavigator.PREVIOUS,
			BankTabNavigator.requestFor(key(KeyEvent.VK_TAB, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK)));
	}

	@Test
	public void rejectsMissingOrExtraModifiersAndNonNumericNavigation()
	{
		assertEquals(BankTabNavigator.NONE, BankTabNavigator.requestFor(key(KeyEvent.VK_1, 0)));
		assertEquals(BankTabNavigator.NONE,
			BankTabNavigator.requestFor(key(KeyEvent.VK_1, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK)));
		assertEquals(BankTabNavigator.NONE,
			BankTabNavigator.requestFor(key(KeyEvent.VK_1, InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK)));
		assertEquals(BankTabNavigator.NONE,
			BankTabNavigator.requestFor(key(KeyEvent.VK_END, InputEvent.CTRL_DOWN_MASK)));
		assertEquals(BankTabNavigator.NONE,
			BankTabNavigator.requestFor(key(KeyEvent.VK_NUMPAD1, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK)));
	}

	@Test
	public void directNavigationRequiresTheRequestedTab()
	{
		assertEquals(3, BankTabNavigator.targetFor(3, 1, counts(4, 2, 1)));
		assertEquals(BankTabNavigator.NONE, BankTabNavigator.targetFor(4, 1, counts(4, 2, 1)));
	}

	@Test
	public void cyclesForwardAndWrapsAcrossExistingTabs()
	{
		int[] tabs = counts(5, 3, 2);
		assertEquals(2, BankTabNavigator.targetFor(BankTabNavigator.NEXT, 1, tabs));
		assertEquals(3, BankTabNavigator.targetFor(BankTabNavigator.NEXT, 2, tabs));
		assertEquals(1, BankTabNavigator.targetFor(BankTabNavigator.NEXT, 3, tabs));
	}

	@Test
	public void cyclesBackwardAndWrapsAcrossExistingTabs()
	{
		int[] tabs = counts(5, 3, 2);
		assertEquals(2, BankTabNavigator.targetFor(BankTabNavigator.PREVIOUS, 3, tabs));
		assertEquals(1, BankTabNavigator.targetFor(BankTabNavigator.PREVIOUS, 2, tabs));
		assertEquals(3, BankTabNavigator.targetFor(BankTabNavigator.PREVIOUS, 1, tabs));
	}

	@Test
	public void cyclingFromAllOrSpecialTabsUsesTheNearestEnd()
	{
		int[] tabs = counts(5, 3, 2);
		assertEquals(1, BankTabNavigator.targetFor(BankTabNavigator.NEXT, 0, tabs));
		assertEquals(3, BankTabNavigator.targetFor(BankTabNavigator.PREVIOUS, 0, tabs));
		assertEquals(1, BankTabNavigator.targetFor(BankTabNavigator.NEXT, 15, tabs));
		assertEquals(3, BankTabNavigator.targetFor(BankTabNavigator.PREVIOUS, 15, tabs));
	}

	@Test
	public void sparseAndEmptyTabSetsAreHandled()
	{
		int[] sparse = counts(7, 0, 4, 0, 1);
		assertEquals(3, BankTabNavigator.targetFor(BankTabNavigator.NEXT, 1, sparse));
		assertEquals(5, BankTabNavigator.targetFor(BankTabNavigator.PREVIOUS, 1, sparse));
		assertEquals(BankTabNavigator.NONE,
			BankTabNavigator.targetFor(BankTabNavigator.NEXT, 0, counts()));
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsMalformedTabSnapshots()
	{
		BankTabNavigator.targetFor(BankTabNavigator.NEXT, 1, new int[8]);
	}

	private static KeyEvent key(int keyCode, int modifiers)
	{
		return new KeyEvent(SOURCE, KeyEvent.KEY_PRESSED, 1L, modifiers, keyCode, KeyEvent.CHAR_UNDEFINED);
	}

	private static int[] counts(int... existingCounts)
	{
		int[] counts = new int[BankTabNavigator.TAB_COUNT];
		System.arraycopy(existingCounts, 0, counts, 0, existingCounts.length);
		return counts;
	}
}

package io.github.iamthecodedecoded.banktabshortcuts;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import org.junit.Test;

import static org.junit.Assert.*;

public class BankTabNumbersOverlayTest
{
	@Test
	public void disabledByDefaultAndDoesNotReadGameState()
	{
		BankTabShortcutsConfig config = new BankTabShortcutsConfig() {};
		assertFalse(config.showTabNumbers());
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) -> { throw new AssertionError("disabled overlay accessed client"); });
		assertEquals(0, render(new BankTabNumbersOverlay(client, config), 0).getRGB(0, 0));
	}

	@Test
	public void labelsOnlyExistingNativeTabsAtTopLeftAndPreservesGraphics()
	{
		BufferedImage image = render(overlay(true, false, false, 10, Color.LIGHT_GRAY), 1);
		assertTrue(changedPixels(image, new Rectangle(12, 12, 15, 17)) > 0); // All
		assertTrue(changedPixels(image, new Rectangle(53, 12, 15, 17)) > 0); // Tab 1
		assertEquals(0, changedPixels(image, new Rectangle(92, 10, 41, 40))); // New tab
		assertEquals(0, changedPixels(image, new Rectangle(10, 30, 82, 20))); // Icons below labels
	}

	@Test
	public void hiddenBankOrTabsProduceNoPixels()
	{
		assertEquals(0, changedPixels(render(overlay(true, true, false, 10, Color.WHITE), 0), new Rectangle(0, 0, 150, 60)));
		assertEquals(0, changedPixels(render(overlay(true, false, true, 10, Color.WHITE), 0), new Rectangle(0, 0, 150, 60)));
	}

	@Test
	public void colorAndSizeChangeRenderedPixels()
	{
		BufferedImage small = render(overlay(true, false, false, 8, Color.RED), 0);
		BufferedImage large = render(overlay(true, false, false, 16, Color.BLUE), 0);
		assertTrue(changedPixels(large, new Rectangle(0, 0, 150, 60)) > changedPixels(small, new Rectangle(0, 0, 150, 60)));
		assertTrue(hasColor(small, Color.RED));
		assertTrue(hasColor(large, Color.BLUE));
	}

	static BankTabNumbersOverlay overlay(boolean enabled, boolean bankHidden, boolean tabsHidden, int size, Color color)
	{
		Widget[] children = new Widget[20];
		for (int tab = 0; tab <= 2; tab++)
		{
			final int index = tab;
			children[10 + tab] = widget(new Rectangle(10 + tab * 41, 10, 41, 40), false, null,
				new String[]{index == 0 ? "View all items" : index == 1 ? "View tab" : "New tab"});
		}
		Widget tabs = widget(new Rectangle(10, 10, 123, 40), tabsHidden, children, null);
		Widget items = widget(new Rectangle(), bankHidden, null, null);
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				if (method.getName().equals("getWidget"))
				{
					return (Integer) args[0] == InterfaceID.Bankmain.TABS ? tabs : items;
				}
				if (method.getName().equals("getVarbitValue"))
				{
					return 1;
				}
				throw new AssertionError("unexpected client access: " + method.getName());
			});
		return new BankTabNumbersOverlay(client, new BankTabShortcutsConfig()
		{
			@Override public boolean showTabNumbers() { return enabled; }
			@Override public int numberSize() { return size; }
			@Override public Color numberColor() { return color; }
		});
	}

	private static Widget widget(Rectangle bounds, boolean hidden, Widget[] children, String[] actions)
	{
		return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[]{Widget.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "isHidden": case "isSelfHidden": return hidden;
					case "getBounds": return bounds;
					case "getChild": return children[(Integer) args[0]];
					case "getActions": return actions;
					default: throw new AssertionError("unexpected widget access: " + method.getName());
				}
			});
	}

	private static BufferedImage render(BankTabNumbersOverlay overlay, int expectedHooks)
	{
		assertEquals(OverlayLayer.MANUAL, overlay.getLayer());
		assertTrue(overlay.getDrawHooks().contains(InterfaceID.Bankmain.TABS));
		BufferedImage image = new BufferedImage(150, 60, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		Color original = graphics.getColor();
		java.awt.Font font = graphics.getFont();
		overlay.render(graphics);
		assertEquals(original, graphics.getColor());
		assertEquals(font, graphics.getFont());
		assertNull(graphics.getClip());
		graphics.dispose();
		return image;
	}

	private static int changedPixels(BufferedImage image, Rectangle area)
	{
		int count = 0;
		for (int y = area.y; y < area.y + area.height; y++)
		{
			for (int x = area.x; x < area.x + area.width; x++)
			{
				if (image.getRGB(x, y) != 0) { count++; }
			}
		}
		return count;
	}

	private static boolean hasColor(BufferedImage image, Color color)
	{
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if (image.getRGB(x, y) == color.getRGB()) { return true; }
			}
		}
		return false;
	}
}

